SELECT id, order_no, user_id, user_name, product_name, category,
       amount, quantity, status, province, city, create_time, update_time
FROM t_order

    deleted = 0

        AND order_no = #{orderNo}


        AND status = #{status}


        AND category = #{category}


        AND user_id = #{userId}


        AND province = #{province}


ORDER BY id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM t_order

    deleted = 0

        AND order_no = #{orderNo}


        AND status = #{status}


        AND category = #{category}


        AND user_id = #{userId}


        AND province = #{province}

SELECT id, order_no, user_id, user_name, product_name, category,
       amount, quantity, status, province, city, create_time, update_time
FROM t_order

    deleted = 0

        AND id < #{cursorId}


        AND order_no = #{orderNo}


        AND status = #{status}


        AND category = #{category}


        AND user_id = #{userId}


        AND province = #{province}


ORDER BY id DESC
LIMIT #{pageSize}

SELECT order_no FROM t_order
WHERE order_no IN

    #{no}
